#include <iostream>
using namespace std;
int main() {
    int t;
    cin >> t;
    while (t--) {
        long long a, b;
        char op;
        cin >> a >> op >> b;
        if (op == '+') cout << a + b << endl;
        else if (op == '-') cout << a - b << endl;
        else if (op == '*') cout << a * b << endl;
        else if (op == '/') {
            if (b == 0) cout << "Error" << endl;
            else cout << a / b << endl;
        } else cout << "Invalid" << endl;
    }
    return 0;
}

