#include <iostream>
using namespace std;
int main() {
    long long bal;
    int n, rej = 0;
    char c = ' ';
    long long amt = 0;
    cin >> bal >> n;
    for (int i = 0; i < n; i++) {
        cin >> c >> amt;
        if (c == 'D') bal += amt;
        else if (c == 'W') {
            if (amt <= bal) bal -= amt;
            else rej++;
        }
    }
    cout << bal << " " << rej << endl;
    return 0;
}

