#include <iostream>
using namespace std;
int main() {
    int n, a[1000];
    cin >> n;
    for (int i = 0; i < n; i++) cin >> a[i];
    int mx = a[0], mn = a[0], good = 0;
    for (int i = 1; i < n; i++) {
        if (a[i] > mx) mx = a[i];
        if (a[i] < mn) mn = a[i];
    }
    for (int i = 0; i < n; i++)
        if (a[i] >= 20 && a[i] <= 30) good++;
    cout << mx << " " << mn << " " << good << endl;
    return 0;
}

