#include <iostream>
using namespace std;
int main() {
    int q[2000];
    int head = 0, tail = 0;
    int m;
    cin >> m;
    while (m--) {
        char op;
        cin >> op;
        if (op == 'E') {
            int x;
            cin >> x;
            q[tail++] = x;
        } else if (op == 'D') {
            if (head >= tail) cout << "empty" << endl;
            else cout << q[head++] << endl;
        } else if (op == 'S') {
            cout << tail - head << endl;
        }
    }
    return 0;
}

