                char o = st[--top];
                if ((c == ')' && o != '(') || (c == ']' && o != '[')) { ok = false; break; }
            }
        }
        if (top != 0) ok = false;
        cout << (ok ? "YES" : "NO") << endl;
    }
    return 0;
}

