#include <iostream>
using namespace std;
bool isPrime(int x) {
    if (x < 2) return false;
    for (long long d = 2; d * d <= x; d++) {
        if (x % d == 0) return false;
    }
    return true;
}
int main() {
    int t, x;
    cin >> t;
    while (t--) {
        cin >> x;
        if (isPrime(x)) cout << "prime" << endl;
        else cout << "not prime" << endl;
    }
    return 0;
}

