#include <cstdio>
int gcd(int a, int b) {
    if (b == 0) return a;
    return gcd(b, a % b);
}
int main() {
    int t, a, b;
    scanf("%d", &t);
    while (t--) {
        scanf("%d %d", &a, &b);
        int g = gcd(a, b);
        long long l = 1LL * a / g * b;
        printf("%d %lld\n", g, l);
    }
    return 0;
}

