#include <cstdio>
int main() {
    int n, q, k;
    int a[1000];
    scanf("%d", &n);
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);
    for (int i = n - 1; i >= 0; i--) {
        printf("%d", a[i]);
        if (i > 0) printf(" ");
    }
    printf("\n");
    int mx = -1000000000;
    for (int i = 0; i < n; i++)
        if (a[i] > mx) mx = a[i];
    printf("%d\n", mx);
    scanf("%d", &q);
    while (q--) {
        scanf("%d", &k);
        if (k >= 1 && k <= n) printf("%d\n", a[k - 1]);
        else printf("invalid\n");
    }
    return 0;
}

